const chatId = $json.chatId;
const p = ($getWorkflowStaticData('global').profiles || {})[chatId];
const text = p
  ? `📄 Your profile

👤 ${p.name || '-'}
📧 ${p.email || '-'}
🎓 ${p.degree || '-'}, ${p.college || '-'}
📈 CGPA: ${p.cgpa ?? '-'}
